"""Deterministic, structured explanations; never generated by an LLM."""


def build(decision):
    c, p = decision.context, decision.policy
    gate = 'approval' if decision.needs_approval else 'autonomous'
    reason = 'forced low-confidence critical escalation' if p and p.forced else (
        'bounded Thompson exploration' if p and p.explore else 'contextual utility')
    return {
        'top_factors': c.top_factors, 'archetype': c.archetype, 'archetype_conf': c.archetype_conf,
        'tier': c.tier, 'risk': c.risk,
        'eligible': sorted(p.scores) if p else [decision.intervention.name],
        'utility_terms': p.scores if p else {}, 'removed': list(p.removed) if p else [],
        'chosen': decision.intervention.name, 'explore': p.explore if p else False,
        'forced': p.forced if p else False, 'gate': gate,
        'gate_reason': decision.gate.text if decision.gate else 'not gated',
        'summary': f'{c.tier} risk ({c.risk:.2f}), {c.archetype}: '
                   f'{decision.intervention.name} via {reason}; {gate}',
    }
